import type {Rect} from './types'
import type {LinearImageRows} from '../image-row-source'

/** Both independent axes were generated by the original Rust bilinear sampler.
 * Include each valid cell and its right/bottom neighbour before rebasing.
 * Alignment lets adjacent tiles and AA phases share immutable source texels. */
export function sourceImageWindow(axes:Float32Array, target:Rect, width:number, height:number):Rect|undefined {
  const span=Math.max(target.w,target.h)
  if(axes.length!==span*8||!Number.isSafeInteger(width)||!Number.isSafeInteger(height)||width<1||height<1)return
  const range=(axis:number,count:number,size:number)=>{
    let lo=size,hi=-1
    for(let i=0;i<count;i++){
      const at=(axis*span+i)*4
      if(axes[at+3]!==-1)return
      if(axes[at+2]===0)continue
      const cell=axes[at]
      if(axes[at+2]!==1||!Number.isInteger(cell)||cell< -1||cell>=size)return
      lo=Math.min(lo,Math.max(0,cell));hi=Math.max(hi,Math.min(size-1,cell+1))
    }
    if(hi<0)return [0,1]
    return [Math.floor(lo/256)*256,Math.min(size,Math.ceil((hi+1)/256)*256)]
  }
  const x=range(0,target.w,width),y=range(1,target.h,height)
  if(!x||!y)return
  const w=x[1]-x[0],h=y[1]-y[0]
  if(w*h>524288||w*h*4>width*height)return
  return {x:x[0],y:y[0],w,h}
}

export function copySourceWindow(image:{width:number;height:number;pixels:Float32Array;linearRows?:()=>LinearImageRows;linearWindow?:(x:number,y:number,w:number,h:number)=>Float32Array}, window:Rect){
  const {x,y,w,h}=window
  if(x<0||y<0||w<1||h<1||x+w>image.width||y+h>image.height)throw Error('Invalid source image window')
  if(image.linearWindow){
    const pixels=image.linearWindow(x,y,w,h)
    if(pixels.length!==w*h*4)throw Error('Incomplete source image window')
    return pixels
  }
  const result=new Float32Array(w*h*4)
  const rows=image.linearRows?.()??[{y:0,height:image.height,pixels:image.pixels}]
  let next=0,copied=0
  for(const row of rows){
    if(row.y!==next||row.height<1||row.pixels.length!==image.width*row.height*4)throw Error('Invalid source image rows')
    next+=row.height
    for(let iy=Math.max(y,row.y);iy<Math.min(y+h,next);iy++){
      const start=((iy-row.y)*image.width+x)*4
      result.set(row.pixels.subarray(start,start+w*4),(iy-y)*w*4);copied++
    }
    if(next>=y+h)break
  }
  if(copied!==h)throw Error('Incomplete source image window')
  return result
}
